#pragma once
#define createPluginFilter createFetTestFilter
#include "../plugins/TracksmithFet/FetProcessor.cpp"
#undef createPluginFilter
#include <iostream>
inline int runFetTests(const char* path,const char* preview){
 auto check=[](bool ok,const char* message){if(!ok){std::cerr<<"FAIL FET: "<<message<<'\n';std::exit(1);}};using namespace TracksmithFet;
 for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int mode=0;mode<5;++mode){Engine e;e.prepare(rate);Settings s;s.ratio=mode;float l[256]{},r[256]{};float* ch[]{l,r};auto signal=[&](float value,int blocks){for(int b=0;b<blocks;++b){std::fill_n(l,256,value);std::fill_n(r,256,value*.5f);e.process(ch,2,256,s);for(float v:l)check(std::isfinite(v),"finite samples");}};signal(1,int(rate/256)+1);const double ratios[]{4,8,12,20,40};double expected=(mode==4?24:18)*(1-1/ratios[mode]);check(std::abs(20*std::log10(l[255])+expected)<.02,"ratio steady gain");check(std::abs(l[255]/r[255]-2)<.001,"stereo link");s.input=6;signal(1,int(rate*.2/256)+1);check(e.reduction()>expected+4,"input increases compression");s.mix=0;signal(1,int(rate*.2/256)+1);check(std::abs(l[255]-1)<.001,"dry mix unity");s.mix=100;s.bypass=true;signal(1,int(rate*.1/256)+1);check(std::abs(l[255]-1)<1.e-6,"bypass unity");s.bypass=false;signal(0,int(rate*10/256)+1);check(l[255]==0&&e.reduction()<.001,"silent recovery");}
 auto onset=[](float attack){Engine e;e.prepare(48000);Settings s;s.attack=attack;float sample[4]{1,1,1,1};float* ch[]{sample};e.process(ch,1,4,s);return e.reduction();};check(onset(20)>onset(800)+1,"faster attack responds sooner");
 juce::ScopedJuceInitialiser_GUI gui;juce::AudioPluginFormatManager formats;formats.addDefaultFormats();juce::OwnedArray<juce::PluginDescription> found;formats.getFormat(0)->findAllTypesForFile(found,juce::String::fromUTF8(path));check(found.size()==1,"VST3 discovery");juce::String error;auto plugin=formats.createPluginInstance(*found[0],48000,256,error);check(plugin!=nullptr,"VST3 loading");check(plugin->getLatencySamples()==0,"zero latency");auto* parameter=plugin->getParameters()[0];parameter->setValueNotifyingHost(.7f);juce::MemoryBlock state;plugin->getStateInformation(state);parameter->setValueNotifyingHost(.2f);plugin->setStateInformation(state.getData(),int(state.getSize()));check(std::abs(parameter->getValue()-.7f)<.001,"state restore");
 FetProcessor native;native.prepareToPlay(48000,256);std::unique_ptr<juce::AudioProcessorEditor> editor(native.createEditorIfNeeded());editor->setVisible(true);juce::Image image(juce::Image::ARGB,editor->getWidth(),editor->getHeight(),true);{juce::Graphics g(image);editor->paintEntireComponent(g,true);}juce::FileOutputStream stream(juce::File(juce::String::fromUTF8(preview)));stream.setPosition(0);juce::PNGImageFormat png;check(png.writeImageToStream(image,stream),"editor render");stream.truncate();std::cout<<"PASS: FET ratios/Slam, input-driven compression, stereo linking, attack ordering, dry mix, bypass, silent recovery, five sample rates, VST3 load/state and native editor render\n";return 0;
}
